 async enableReservationAlerts(){if(typeof Notification==='undefined')return this.toast('This browser supports in-app reservation reminders only.');try{const granted=await Notification.requestPermission();this.toast(granted==='granted'?'RESERVATION NOTIFICATIONS ENABLED':'In-app reservation reminders remain active while the app is open.');}catch(e){this.toast(e.message);}}

 openReservations(table=''){const e=this.escape;this.openDialog('Reservations',`<div class="reservation-toolbar"><div><label for="resDate">Date</label><input id="resDate" class="field" type="date" value="${this.connection.state.day}"></div><button id="enableReservationAlerts" class="full">ENABLE RESERVATION NOTIFICATIONS</button><p class="helper">Reminder 2 hours before each reservation while this app is open. Allow notifications for a system alert.</p><button id="upcomingReservations" class="full">SHOW ALL UPCOMING RESERVATIONS</button></div><div id="reservationList" class="reserved-list"></div><form id="reservationForm"><h3>New Reservation · minimum 6 guests</h3><div class="reservation-form-grid"><div><label for="resName">Guest name</label><input id="resName" class="field" maxlength="100" required></div><div><label for="resTime">Time</label><input id="resTime" type="time" class="field" required></div><div><label for="resPeople">Guests</label><input id="resPeople" type="number" class="field" min="6" max="120" value="6" required></div><div><label for="resPhone">Phone · optional</label><input id="resPhone" type="tel" class="field" maxlength="30"></div><div><label for="resTable">Table · optional</label><select id="resTable" class="field"><option value="">Not assigned</option>${this.connection.config.tables.map(t=>`<option value="${e(t.id)}" ${t.id===table?'selected':''}>${e(t.id)}</option>`).join('')}</select></div><div><label for="resNote">Notes · optional</label><input id="resNote" class="field" maxlength="300"></div></div><button class="primary full" id="saveReservation">SAVE RESERVATION</button></form>`);let showUpcoming=true;const render=()=>{const day=document.getElementById('resDate')?.value,box=document.getElementById('reservationList');if(!box)return;const rows=Object.entries(this.reservations||{}).filter(([,r])=>showUpcoming?r.date>=this.connection.state.day:r.date===day).sort((a,b)=>(a[1].date+' '+a[1].time).localeCompare(b[1].date+' '+b[1].time));box.innerHTML=rows.length?'<div class="reservation-table-scroll"><table class="reservation-table"><caption>Upcoming Reservations</caption><thead><tr>'+['Date','Time','Guest name','Guests','Phone','Table','Notes','Actions'].map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(([id,r])=>`<tr data-res-row="${e(id)}">${[['date','date'],['time','time'],['name','text'],['people','number'],['phone','tel'],['table','text'],['note','text']].map(([key,type])=>`<td><input aria-label="${e(key)}" data-res-field="${key}" type="${type}" value="${e(String(r[key]??''))}" ${key==='people'?'min="6" max="120"':key==='name'?'maxlength="100"':key==='phone'?'maxlength="30"':key==='note'?'maxlength="300"':''} disabled></td>`).join('')}<td><div class="reservation-row-actions"><button data-res-edit="${e(id)}">EDIT</button><button data-res-save="${e(id)}" class="primary" disabled>SAVE</button><button data-res-delete="${e(id)}" class="danger">DELETE</button></div></td></tr>`).join('')+'</tbody></table></div>':'<p class="helper">No reservations for this date.</p>';box.querySelectorAll('[data-res-edit]').forEach(b=>b.onclick=()=>{const row=b.closest('tr');row.querySelectorAll('[data-res-field]').forEach(input=>input.disabled=false);const validate=()=>{const n=Number(row.querySelector('[data-res-field=people]').value);row.querySelector('[data-res-save]').disabled=!Number.isInteger(n)||n<6||n>120;};row.querySelectorAll('[data-res-field]').forEach(input=>input.oninput=validate);validate();row.classList.add('editing');row.querySelector('[data-res-field="name"]').focus();});box.querySelectorAll('[data-res-save]').forEach(b=>b.onclick=async()=>{const row=b.closest('tr'),value={...this.reservations[b.dataset.resSave]};for(const input of row.querySelectorAll('[data-res-field]'))value[input.dataset.resField]=input.dataset.resField==='people'?Number(input.value):input.value.trim();if(!value.date||!value.time||!value.name||!Number.isInteger(value.people)||value.people<6||value.people>120)return this.toast('Complete date, time, name and 6–120 guests.');if(value.table&&!this.connection.config.tables.some(t=>t.id===value.table))return this.toast('Choose a valid table.');b.disabled=true;try{await this.connection.ref.child('reservations/'+b.dataset.resSave).set(value);this.toast('RESERVATION SAVED');render();}catch(error){b.disabled=false;this.toast(error.message);}});box.querySelectorAll('[data-res-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this reservation?'))try{await this.connection.ref.child('reservations/'+b.dataset.resDelete).remove();this.toast('RESERVATION DELETED');}catch(e){this.toast(e.message);}});};if(!this.reservationWatching){this.reservationWatching=true;this.watch(this.connection.ref.child('reservations'),snap=>{this.reservations=snap.val()||{};this.onReservationsChange?.();this.drawReservations?.();});}this.drawReservations=render;document.getElementById('resDate').onchange=()=>{showUpcoming=false;render();};document.getElementById('enableReservationAlerts').onclick=()=>this.enableReservationAlerts();document.getElementById('upcomingReservations').onclick=()=>{showUpcoming=true;render();};render();const validateGuests=()=>{const n=Number(document.getElementById('resPeople').value);document.getElementById('saveReservation').disabled=!Number.isInteger(n)||n<6||n>120;};document.getElementById('resPeople').oninput=validateGuests;validateGuests();document.getElementById('reservationForm').onsubmit=async event=>{event.preventDefault();try{const form=document.getElementById('reservationForm'),id=form.dataset.editId||'res_'+this.connection.now()+'_'+HostCore.uid();form.dataset.editId=id;const value={date:document.getElementById('resDate').value,name:document.getElementById('resName').value.trim(),time:document.getElementById('resTime').value,people:Number(document.getElementById('resPeople').value),phone:document.getElementById('resPhone').value.trim(),note:document.getElementById('resNote').value.trim(),table:document.getElementById('resTable').value,at:this.connection.now()};if(!value.date||!value.name||!value.time||!Number.isInteger(value.people)||value.people<6||value.people>120)throw Error('Complete the reservation fields. Minimum 6 guests.');await this.connection.ref.child('reservations/'+id).set(value);form.reset();delete form.dataset.editId;document.getElementById('resPeople').value=6;this.toast('RESERVATION SAVED');}catch(e){this.toast(e.message);}};}
